'use strict';
const VIBE_CATEGORIES={all:'All reactions','food-joke':'Food banter',motivation:'Encouragement',meal:'Food logs',movement:'Tiny moves',water:'Water check-ins',budget:'Budget & plans',rest:'Slow days',progress:'Small wins'};
const VIBE_CHAT_PROMPTS={budget:'Help me plan lunch for ₱100.',meal:'I cooked and logged my lunch today.',movement:'I walked for five minutes today.',water:'I drank a glass of water.',rest:'I am tired and need a rest day.',progress:'I finished my plan today. Small win!',motivation:'Give me some motivation to get started.','food-joke':'Is pancit canton the healthiest food?'};
let vibeGalleryFilter='all',activeVibeReason='progress',activeVibePhotoId=null;
function vibeImagesEnabled(){return state.platinum===true&&state.coachType==='kaincheck'&&state.coach.vibe===true;}
function vibeMoment(){const saved=state.vibePhotos||{};return saved.day===localDay()?{reason:Object.hasOwn(VIBE_CATEGORIES,saved.reason)&&saved.reason!=='all'?saved.reason:'motivation',offset:Math.max(0,Number(saved.offset)||0)}:{reason:'motivation',offset:0};}
function setVibeMoment(reason,persist=false){if(!vibeImagesEnabled())return;const current=vibeMoment();state.vibePhotos={day:localDay(),reason:reason==='plan'?'budget':Object.hasOwn(VIBE_CATEGORIES,reason)&&reason!=='all'?reason:'motivation',offset:(current.offset+1)%10000};if(persist)save();}
function pickVibePhoto(reason='motivation',offset=vibeMoment().offset){const pool=VIBE_PHOTOS.filter(p=>p.tags.includes(reason)),photos=pool.length?pool:VIBE_PHOTOS,seed=localDay()+'|'+(state.coach.templateId||'kai')+'|'+reason;let hash=0;for(const char of seed)hash=(hash*31+char.charCodeAt(0))>>>0;return photos[(hash+offset)%photos.length];}
function vibePhotoImage(photo,className=''){return `<img class="${className}" data-vibe-image="${photo.id}" src="${photo.image}" alt="${esc(photo.alt)}" loading="lazy" decoding="async">`;}
function dailyVibeMarkup(){if(!vibeImagesEnabled())return '';const moment=vibeMoment(),photo=pickVibePhoto(moment.reason);return `<section class="daily-vibe" aria-label="Daily Vibe"><button class="daily-vibe-picture" data-open-vibe="${photo.id}" aria-label="Open this Vibe reaction">${vibePhotoImage(photo)}</button><div class="daily-vibe-copy"><small class="vibe-reaction-label">✨ VIBE MODE · JUST FOR FUN</small><h2>${VIBE_CATEGORIES[moment.reason]}</h2><p>${esc(photo.caption)}</p><div class="vibe-reaction-actions"><button class="text-btn" data-action="shuffle-vibe">Another vibe</button><button class="text-btn" data-action="vibe-gallery">Browse photos</button></div></div></section>`;}
function openVibeGallery(filter='all'){if(!vibeImagesEnabled()){toast('Turn on Vibe Mode in your KainCheck coach settings to see animal reactions.');return;}vibeGalleryFilter=Object.hasOwn(VIBE_CATEGORIES,filter)?filter:'all';const photos=VIBE_PHOTOS.filter(p=>vibeGalleryFilter==='all'||p.tags.includes(vibeGalleryFilter));showModal('Your Vibe Gallery',`<p class="subtle">the group chat escaped. pick your reaction 💀</p><div class="filters vibe-gallery-filters" role="group" aria-label="Reaction categories">${Object.entries(VIBE_CATEGORIES).map(([id,label])=>`<button class="chip ${vibeGalleryFilter===id?'selected':''}" data-vibe-filter="${id}" aria-pressed="${vibeGalleryFilter===id}">${label}</button>`).join('')}</div><div class="vibe-photo-gallery">${photos.map(p=>`<button class="vibe-gallery-tile" data-open-vibe="${p.id}" aria-label="Open reaction: ${esc(p.alt)}">${vibePhotoImage(p)}<span>${esc(p.caption)}</span></button>`).join('')}</div><p class="vibe-gallery-note">These are playful reactions. Food guidance and nutrition cautions stay in your food log.</p>`);activeModal='vibe-gallery';}
function showAnimalVibe(reason='progress',photoId=null){if(!vibeImagesEnabled()){toast('Vibe Mode is off. You can enable it in your KainCheck coach settings.');return;}activeVibeReason=Object.hasOwn(VIBE_CATEGORIES,reason)&&reason!=='all'?reason:'progress';const photo=VIBE_PHOTOS.find(p=>p.id===photoId)||pickVibePhoto(activeVibeReason);activeVibePhotoId=photo.id;showModal('Your Vibe card',`<figure class="animal-vibe-card">${vibePhotoImage(photo)}<figcaption><small class="vibe-reaction-label">✨ VIBE MODE · JUST FOR FUN</small><h3>${VIBE_CATEGORIES[activeVibeReason]}</h3><p>${esc(photo.caption)}</p></figcaption></figure><p class="subtle">the group chat has entered the wellness arc.</p><div class="sheet-actions"><button class="secondary" data-action="vibe-gallery">Browse photos</button><button class="primary" data-action="shuffle-vibe">Another reaction</button></div><button class="text-btn vibe-card-done" data-action="close">Done</button>`);activeModal='vibe-photo';}
function vibeSensitiveTopic(text){return /\b(?:sodium|salt|sugar)\b|allerg|diabet|kidney|blood.?pressure|hypertens|\bheart\b|pregnan|medic|doctor|clinician|dietitian|diagnos|symptom|\bpain\b|injur|dizz|faint|vomit|nausea|unsafe|emergen|suicid|self.?harm|kill myself|hurt myself|depress|disorder|anorex|purging|calorie restriction/i.test(text);}
function vibeSeriousTopic(text){return /allerg|diabet|kidney|blood.?pressure|hypertens|\bheart\b|pregnan|medic|doctor|clinician|dietitian|diagnos|symptom|\bpain\b|injur|dizz|faint|vomit|nausea|poison|spoiled|raw chicken|undercook|unsafe|safe to eat|food safety|emergen|suicid|self.?harm|kill myself|hurt myself|depress|disorder|anorex|purging|calorie restriction|\b(?:baby|babies|child|children|toddler)\b|(?:3|three|thrice|3x|tatlong).{0,25}(?:day|daily|araw)|(?:every|each) (?:day|meal)|how (?:much|often)|maximum|daily (?:limit|intake)|sodium (?:limit|restriction)|too much sodium/i.test(String(text));}
function vibeFoodBanter(input){const s=String(input).toLowerCase();return !vibeSeriousTopic(s)&&/healthiest|healthi?est|most healthy|super healthy|pinaka.?healthy|pinaka.?masustansya|peak nutrition|pinnacle of nutrition|healthy (?:right|di ba|diba)|\bhealthy\b.{0,15}\?/.test(s)&&/pancit|pansit|canton|noodle|ramen|instant|hotdog|chips|fries|pizza|burger|ice.?cream|soda|soft.?drink|milk.?tea|food|pagkain/.test(s);}
function vibeChatTopic(input){
 const s=String(input).toLowerCase().replace(/[’‘]/g,"'");
 if(vibeSeriousTopic(s)||vibeSensitiveTopic(s))return null;
 if(/\btired\b|\bsleep\w*|\bnap\b|\brest\b|exhaust|drained|low energy|brain fog|head empty|buffering|can't (?:focus|think)|\bpagod\b|\bantok\b|pahinga|\blutang\b|\bsabaw\b/.test(s))return 'rest';
 if(/\bwater\b|hydrat|\bsip\b|\btubig\b|\bthirsty\b|\buhaw\b/.test(s))return 'water';
 if(/small win|\bproud\b|celebrat|achievement|\bprogress\b|(?:finished|completed|done with).{0,25}(?:plan|goal|task|routine)|\bnatapos\b|\btagumpay\b/.test(s))return 'progress';
 if(/\bbudget\b|\bcheap\b|afford|pesos|\bphp\b|₱|\bcost\b|\bprice\b|\bwallet\b|grocer|\btipid\b|\bgastos\b|\bbarya\b|\bplan(?:ning)?\b/.test(s))return 'budget';
 if(/\bwalk\w*|\bmov(?:e|ed|ement|ing)\b|workout|\bexercise\b|\bdanc\w*|\bcycl\w*|\bbike\b|\bstep\w*|\bgym\b|\bstretch\w*|\bsayaw\b|\blakad\b|naglakad/.test(s))return 'movement';
 if(/\bcook\w*|\bmeal\w*|\bfood\b|\blunch\b|\bdinner\b|\bbreakfast\b|\brecipe\w*|\bkitchen\b|\bsnack\w*|\bate\b|\beating\b|\blogged\b|\bluto\b|nagluto|\bkain\b|kumain|pagkain|kusina/.test(s))return 'meal';
 if(/goofy|meme|funny|\bjoke\b|encourag|motivat|good vibes|cheer me|hype me|\bstart\w*|\bbegin\w*|\bsimula\b|\bkaya ko\b/.test(s))return 'motivation';
 return null;
}
function nextChatVibePhoto(topic){
 const pool=VIBE_PHOTOS.filter(p=>p.tags.includes(topic));if(!pool.length)return null;
 for(let i=state.messages.length-1;i>=0;i--){const message=state.messages[i];if(message.role!=='bot'||message.error)continue;const previous=pool.findIndex(p=>p.id===message.vibePhoto);if(previous!==-1)return pool[(previous+1)%pool.length];}
 return pickVibePhoto(topic,0);
}
function openVibeReactionIdeas(){
 if(!vibeImagesEnabled()){toast('Turn on Vibe Mode in your KainCheck coach settings first.');return;}
 showModal('Try Vibe reactions',`<p class="subtle">Talk naturally about your day, or pick a prompt below and send it. Photos follow the topic and rotate with new replies.</p><div class="vibe-prompt-list">${Object.entries(VIBE_CHAT_PROMPTS).map(([id,prompt])=>`<button class="vibe-prompt-choice" data-vibe-example="${id}"><strong>${VIBE_CATEGORIES[id]}</strong><span>${esc(prompt)}</span></button>`).join('')}</div><button class="secondary" data-action="vibe-gallery">Browse all photos</button>`);activeModal='vibe-ideas';
}
function decorateVibeReply(message,input){
 const result={...message};delete result.vibePhoto;delete result.vibeReaction;delete result.vibeTopic;
 if(!vibeImagesEnabled()||message.error||message.refreshError||vibeSeriousTopic(input)||vibeSeriousTopic(message.text))return result;
 if(vibeFoodBanter(input)&&!vibeSeriousTopic(message.text)){result.vibePhoto='glam-pigeon';result.vibeReaction='food-joke';return result;}
 const topic=vibeChatTopic(input),photo=topic&&nextChatVibePhoto(topic);if(photo){result.vibePhoto=photo.id;result.vibeReaction='topic';result.vibeTopic=topic;}return result;
}
function vibeChatReactionMarkup(message){
 if(!vibeImagesEnabled()||message.error||message.refreshError)return '';
 const foodBit=message.vibePhoto==='glam-pigeon'&&message.vibeReaction==='food-joke';
 const photo=VIBE_PHOTOS.find(p=>p.id===message.vibePhoto),topicBit=message.vibeReaction==='topic'&&photo?.tags.includes(message.vibeTopic);
 if(foodBit||topicBit?vibeSeriousTopic(message.text):vibeSensitiveTopic(message.text||''))return '';
 return photo?`<figure class="chat-vibe-reaction ${foodBit?'food-banter':''}">${vibePhotoImage(photo)}<figcaption>${esc(photo.caption)}<small>${foodBit?'Vibe Mode · sarcasm. The real food advice is in the reply above.':'Vibe reaction · just for fun'}</small></figcaption></figure>`:'';
}
function syncVibeVisibility(){if(!vibeImagesEnabled()&&['vibe-photo','vibe-gallery','vibe-ideas'].includes(activeModal))closeModal();}
function installVibeImages(){
 showVibe=showAnimalVibe;Object.assign(actions,{'vibe-gallery':()=>openVibeGallery(),'vibe-reaction-ideas':openVibeReactionIdeas,'shuffle-vibe':()=>{if(!vibeImagesEnabled())return;const modal=activeModal==='vibe-photo',reason=modal?activeVibeReason:vibeMoment().reason;setVibeMoment(reason,true);if(modal){const pool=VIBE_PHOTOS.filter(p=>p.tags.includes(reason)),index=pool.findIndex(p=>p.id===activeVibePhotoId);showAnimalVibe(reason,pool[(index+1)%pool.length]?.id);}else render(true);}});
 const baseToday=today;today=()=>{const markup=baseToday();if(!vibeImagesEnabled())return markup;return markup.replace(/<div class="cheer">[\s\S]*?<\/div>/,'').replace('<button class="wellness-home-entry"',dailyVibeMarkup()+'<button class="wellness-home-entry"');};
 const baseCoach=coach;coach=()=>{const markup=baseCoach();return vibeImagesEnabled()?markup.replace('<div class="chat-suggestions">','<div class="chat-suggestions"><button data-action="vibe-reaction-ideas">Reaction ideas</button><button data-prompt="Give me a little goofy encouragement for a small daily win.">Goofy encouragement</button>'):markup;};
 const baseWater=actions.water;actions.water=()=>{setVibeMoment('water');baseWater();};
 const baseComplete=completePlan;completePlan=id=>{const item=state.plan.find(p=>p.id===id);if(item&&!item.done)setVibeMoment(item.kind==='activity'?'movement':'plan');baseComplete(id);};
 document.addEventListener('click',e=>{const open=e.target.closest('[data-open-vibe]');if(open&&vibeImagesEnabled()){const photo=VIBE_PHOTOS.find(p=>p.id===open.dataset.openVibe);if(photo)showAnimalVibe(photo.tags[0],photo.id);}const filter=e.target.closest('[data-vibe-filter]');if(filter)openVibeGallery(filter.dataset.vibeFilter);const example=e.target.closest('[data-vibe-example]');if(example&&vibeImagesEnabled()){const prompt=VIBE_CHAT_PROMPTS[example.dataset.vibeExample];if(prompt){closeModal();navigate('coach');$('#chat-input').value=prompt;$('#chat-input').focus();}}});
 document.addEventListener('submit',e=>{if(e.target.id==='activity-form'&&!e.target.dataset.edit&&vibeImagesEnabled()){setVibeMoment('movement',true);if(screen==='today')render(true);}});
}
